import{_ as s,y as i,a as g,o as l,a2 as o,D as n,g as e,I as a}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Product Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"attribute/product-attribute.md","filePath":"attribute/product-attribute.md","lastUpdated":1789441803000}'),d={name:"attribute/product-attribute.md"};function u(h,t,c,p,b,f){const r=i("ImagePopup");return l(),g("div",null,[t[6]||(t[6]=o('<h1 id="product-attributes" tabindex="-1">Product Attributes <a class="header-anchor" href="#product-attributes" aria-label="Permalink to &quot;Product Attributes&quot;">​</a></h1><p>Attributes are the fields that describe your products, such as <strong>Color</strong>, <strong>Size</strong>, <strong>Material</strong> or <strong>Brand</strong>. Each attribute has a type, a name in each language and settings that decide where it shows: as a field on the product edit screen, as a filter on category pages, on the product page and on the compare page. <strong>Brand</strong> isn&#39;t a separate feature: it&#39;s a <strong>Select</strong> attribute, and each brand is one of its options.</p><p>An attribute appears on the product edit screen once you add it to an <a href="./attribute-family.html">attribute family</a>.</p><h2 id="the-attributes-list" tabindex="-1">The attributes list <a class="header-anchor" href="#the-attributes-list" aria-label="Permalink to &quot;The attributes list&quot;">​</a></h2><p>Go to <strong>Catalog &gt;&gt; Attributes</strong>.</p>',5)),n(r,{src:"/images/attribute/attributes-grid.png",alt:"Attributes list under Catalog >> Attributes"}),t[7]||(t[7]=o('<p>Each row shows the attribute&#39;s <strong>ID</strong>, <strong>Code</strong>, <strong>Name</strong> and <strong>Type</strong>, then <strong>True</strong> or <strong>False</strong> for <strong>Required</strong>, <strong>Unique</strong>, <strong>Locale Based</strong> and <strong>Channel Based</strong>, and the date in <strong>Created At</strong>.</p><ul><li><strong>Search:</strong> type in the search box to find attributes by ID, code, name or type.</li><li><strong>Filter:</strong> click <strong>Filter</strong> to filter by any column. <strong>Type</strong> offers a list of the types, and <strong>Created At</strong> a date range.</li><li><strong>Sort:</strong> click a column in the header row.</li><li><strong>Edit</strong> (the pencil) opens the attribute, and <strong>Delete</strong> (the bin) deletes it.</li></ul><h3 id="system-attributes" tabindex="-1">System attributes <a class="header-anchor" href="#system-attributes" aria-label="Permalink to &quot;System attributes&quot;">​</a></h3><p>The attributes every store needs are system attributes, and they can&#39;t be deleted: <strong>SKU</strong>, <strong>Name</strong>, <strong>URL Key</strong>, <strong>Tax Category</strong>, <strong>New</strong>, <strong>Featured</strong>, <strong>Visible Individually</strong>, <strong>Status</strong>, <strong>Short Description</strong>, <strong>Description</strong>, <strong>Price</strong>, <strong>Special Price</strong>, <strong>Special Price From</strong>, <strong>Special Price To</strong>, <strong>Meta Title</strong>, <strong>Meta Keywords</strong>, <strong>Weight</strong>, <strong>Guest Checkout</strong>, <strong>Product Number</strong>, <strong>Manage Stock</strong>, <strong>Allow RMA</strong> and <strong>RMA Rules</strong>. Deleting one from its row shows <strong>Can not delete system Attribute</strong>, and a mass delete that includes one shows <strong>Attribute Deleted Failed</strong> and deletes nothing. You can still edit their names and settings.</p><h2 id="create-an-attribute" tabindex="-1">Create an attribute <a class="header-anchor" href="#create-an-attribute" aria-label="Permalink to &quot;Create an attribute&quot;">​</a></h2>',5)),e("ol",null,[t[1]||(t[1]=o("<li><p>Go to <strong>Catalog &gt;&gt; Attributes</strong>.</p></li><li><p>Click <strong>Create Attributes</strong>. The <strong>Add Attribute</strong> page opens.</p></li><li><p>In <strong>Label</strong>, enter the <strong>Admin</strong> name, the name you see in the admin panel.</p></li><li><p>Enter the name shoppers see in each language, such as <strong>English (EN)</strong>.</p></li><li><p>In <strong>General</strong>, enter the <strong>Attribute Code</strong>. Start with a letter and use letters, numbers and underscores, such as <code>fabric_color</code>.</p></li>",5)),e("li",null,[t[0]||(t[0]=e("p",null,[a("Choose the "),e("strong",null,"Attribute Type"),a(". The sections and settings for that type appear.")],-1)),n(r,{src:"/images/attribute/create-attribute.png",alt:"Add Attribute page with the Label section and the General, Validations and Configuration sections for a Select attribute"})]),t[2]||(t[2]=o('<li><p>For a <strong>Checkbox</strong>, <strong>Select</strong> or <strong>Multiselect</strong> attribute, add its options. See <a href="#options">Options</a>.</p></li><li><p>In <strong>Validations</strong>, choose the checks the product value must pass. See <a href="#validations">Validations</a>.</p></li><li><p>In <strong>Configuration</strong>, tick the settings you need. See <a href="#configuration">Configuration</a>.</p></li><li><p>Click <strong>Save Attribute</strong>.</p></li>',4))]),t[8]||(t[8]=o('<p>To add the new attribute to products, <a href="#add-the-attribute-to-a-family">add it to a family</a>.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>The <strong>Options</strong> section appears for <strong>Checkbox</strong>, <strong>Select</strong> and <strong>Multiselect</strong> attributes. Each option is a choice, such as <strong>Red</strong> for <strong>Color</strong> or a brand name for <strong>Brand</strong>.</p><p>For a <strong>Select</strong> attribute, <strong>Input Options</strong> decides how shoppers choose between the options of a configurable product: <strong>Dropdown</strong>, <strong>Color Swatch</strong>, <strong>Image Swatch</strong> or <strong>Text Swatch</strong>. See <a href="./attribute-input.html#what-shoppers-see">What shoppers see</a>.</p><p>To add an option:</p>',5)),e("ol",null,[t[4]||(t[4]=o("<li><p>In <strong>Options</strong>, click <strong>Add Row</strong>. The <strong>Add Option</strong> dialog opens.</p></li><li><p>For a <strong>Color Swatch</strong>, pick the <strong>Color</strong>. For an <strong>Image Swatch</strong>, upload the <strong>Image</strong>.</p></li><li><p>Enter the <strong>Admin</strong> name.</p></li>",3)),e("li",null,[t[3]||(t[3]=e("p",null,"Enter the option's name in each language. The name in your default channel's default language is required.",-1)),n(r,{src:"/images/attribute/attribute-add-option.png",alt:"Add Option dialog with a navy blue color and the option's name in each language"})]),t[5]||(t[5]=e("li",null,[e("p",null,[a("Click "),e("strong",null,"Save Option"),a(". The option is added to the list.")])],-1))]),t[9]||(t[9]=o("<p>After you add the options:</p><ul><li><strong>Reorder:</strong> drag an option by its handle. Shoppers see the options in this order.</li><li><strong>Change:</strong> click the pencil on the row.</li><li><strong>Remove:</strong> click the bin on the row, and confirm.</li><li><strong>Image swatch text:</strong> for an <strong>Image Swatch</strong>, enter the <strong>Alt Text</strong> and <strong>File Name</strong> under each image.</li><li><strong>Empty option:</strong> for a <strong>Select</strong> attribute, tick <strong>Create default empty option</strong>. The <strong>Add Option</strong> dialog opens with no required names. Click <strong>Save Option</strong> to add the empty option.</li></ul>",2)),n(r,{src:"/images/attribute/attribute-options-color-swatch.png",alt:"Options section of the Color attribute set to Color Swatch, with a swatch for each color"}),t[10]||(t[10]=o('<p>The options are saved when you click <strong>Save Attribute</strong>. After saving an attribute with color or image swatches, open it again to check that every option shows its swatch.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong>Attribute Code:</strong> the attribute&#39;s unique code. It can&#39;t be changed later.</li><li><strong>Attribute Type:</strong> what you fill in on the product. See <a href="./attribute-input.html">Attribute Input Types</a>. It can&#39;t be changed later.</li><li><strong>Enable Wysiwyg Editor:</strong> for a <strong>Textarea</strong> attribute, shows a text editor with formatting instead of a plain text box.</li><li><strong>Default Value:</strong> for a <strong>Boolean</strong> attribute, the value products have until you set one. Enter <code>1</code> for on or <code>0</code> for off.</li></ul><h3 id="validations" tabindex="-1">Validations <a class="header-anchor" href="#validations" aria-label="Permalink to &quot;Validations&quot;">​</a></h3><ul><li><strong>Input Validation:</strong> for a <strong>Text</strong> attribute, the format the value must have: <strong>Number</strong>, <strong>Email</strong>, <strong>Decimal</strong>, <strong>URL</strong> or <strong>Regex</strong>. For <strong>Regex</strong>, enter the pattern in <strong>Regex</strong> between slashes, such as <code>/^[A-Z]{2}-[0-9]{4}$/</code>.</li><li><strong>Is Required:</strong> the field is marked with an asterisk on the product edit screen, and the product can&#39;t be saved without a value.</li><li><strong>Is Unique:</strong> no two products can have the same value. Saving a product with a value another product already has shows that the value has already been taken.</li></ul>',5)),n(r,{src:"/images/attribute/validation.png",alt:"Validations section with Regex input validation, a pattern and Is Required ticked"}),t[11]||(t[11]=o('<h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Each setting has an information icon that explains it when you point to it.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Value Per Locale</strong></td><td>The product field gets a language badge and holds a separate value for each language, so you can translate it. It doesn&#39;t apply to <strong>Checkbox</strong>, <strong>Select</strong>, <strong>Multiselect</strong> and <strong>Boolean</strong> attributes: the first three translate their option names instead, and Boolean attributes show <strong>Yes</strong> or <strong>No</strong>.</td></tr><tr><td><strong>Value Per Channel</strong></td><td>The product field holds a separate value for each channel, and gets a channel badge when you have more than one channel.</td></tr><tr><td><strong>Use To Create Configurable Product</strong></td><td>For <strong>Select</strong> attributes. Configurable products can use the attribute to make their variants, such as a shirt in each <strong>Color</strong> and <strong>Size</strong>. A configurable attribute has the same value in every language and channel, so <strong>Value Per Locale</strong> and <strong>Value Per Channel</strong> are switched off when you save.</td></tr><tr><td><strong>Visible on Product View Page on Front-end</strong></td><td>Lists the attribute and the product&#39;s value under <strong>Additional Information</strong> on the product page.</td></tr><tr><td><strong>Attribute is comparable</strong></td><td>Adds the attribute as a row on the <strong>Product Compare</strong> page. Comparison is switched on in <a href="./../configure/configurable-choices.html">Product Settings</a>.</td></tr><tr><td><strong>Use in Layered Navigation</strong></td><td>For <strong>Checkbox</strong>, <strong>Select</strong>, <strong>Multiselect</strong>, <strong>Boolean</strong> and <strong>Price</strong> attributes. Lets you choose the attribute as a filter for a category, under <a href="./../category/create-category.html#filterable-attributes">Filterable Attributes</a>. <strong>Price</strong> shows as a range slider, and the other types as checkboxes.</td></tr></tbody></table><h2 id="edit-an-attribute" tabindex="-1">Edit an attribute <a class="header-anchor" href="#edit-an-attribute" aria-label="Permalink to &quot;Edit an attribute&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Attributes</strong>.</li><li>Click <strong>Edit</strong> on the attribute&#39;s row. The <strong>Edit Attribute</strong> page opens.</li><li>Change the names, options or settings.</li><li>Click <strong>Save Attribute</strong>.</li></ol><h3 id="what-can-t-be-changed-after-saving" tabindex="-1">What can&#39;t be changed after saving <a class="header-anchor" href="#what-can-t-be-changed-after-saving" aria-label="Permalink to &quot;What can&#39;t be changed after saving&quot;">​</a></h3><p>Some choices shape the values products already hold, so they&#39;re fixed once the attribute is saved:</p><ul><li>the <strong>Attribute Code</strong> and <strong>Attribute Type</strong>;</li><li>the <strong>Input Validation</strong> and its <strong>Regex</strong>;</li><li><strong>Value Per Locale</strong> and <strong>Value Per Channel</strong>;</li><li><strong>Is Unique</strong>, once it&#39;s on.</li></ul><p>To change one of these, create a new attribute.</p><h2 id="delete-an-attribute" tabindex="-1">Delete an attribute <a class="header-anchor" href="#delete-an-attribute" aria-label="Permalink to &quot;Delete an attribute&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Attributes</strong>.</li><li>Click <strong>Delete</strong> on the attribute&#39;s row.</li><li>Confirm the deletion.</li></ol><p>To delete several attributes at once:</p><ol><li>Go to <strong>Catalog &gt;&gt; Attributes</strong>.</li><li>Tick the attributes.</li><li>Open <strong>Select Action</strong>.</li><li>Choose <strong>Delete</strong>.</li><li>Confirm the deletion.</li></ol><p>Deleting an attribute removes it from every family and deletes the values products hold for it. It can&#39;t be undone. System attributes can&#39;t be deleted: when your selection includes one, <strong>Attribute Deleted Failed</strong> appears and nothing is deleted. An attribute that configurable products use for their variants can&#39;t be deleted either, and <strong>Attribute Deleted Failed</strong> appears.</p><h2 id="add-the-attribute-to-a-family" tabindex="-1">Add the attribute to a family <a class="header-anchor" href="#add-the-attribute-to-a-family" aria-label="Permalink to &quot;Add the attribute to a family&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Attribute Families</strong>.</li><li>Click <strong>Edit</strong> on the family&#39;s row.</li><li>Drag the attribute from <strong>Unassigned Attributes</strong> into a group.</li><li>Click <strong>Save Attribute Family</strong>.</li></ol><p>The attribute now appears as a field on the edit screen of the family&#39;s products. See <a href="./attribute-family.html">Attribute Families</a>.</p>',17))])}const T=s(d,[["render",u]]);export{_ as __pageData,T as default};
